def evaluate(current_reputation, observation, my_history, round_num):
    # Exponentially weighted moving average of observed actions.
    # Recent actions have slightly more weight.
    action_val = 1.0 if observation['action'] == 'cooperate' else -1.0
    alpha = 0.2  # learning rate; can be tuned
    new_reputation = current_reputation * (1 - alpha) + action_val * alpha
    # Clip to [-1, 1]
    return max(-1.0, min(1.0, new_reputation))

def decide(recipient_reputation, round_num, my_history):
    # Start by defecting (suspicious start)
    if round_num == 0:
        return False

    # Count consecutive defections of the agent itself (not partner actions)
    consec_def = 0
    for entry in reversed(my_history):
        if entry['my_action'] == 'defect':
            consec_def += 1
        else:
            break

    # After several own defections, become more forgiving
    if consec_def >= 3:
        # Cooperate unless reputation is very low
        return recipient_reputation > -0.5
    else:
        # Normal reputation‑based threshold
        return recipient_reputation > 0.2
